<script setup lang="ts">
import {computed,ref,watch,nextTick} from 'vue';import {useI18n} from 'vue-i18n';import {useNewsroom,videoSources} from '../api/newsroom';import {assetUrl,apiUrl} from '../lib/urls';import photos from '../content/team-photos.json';import {racePhotos} from '../content/race-photos';import {safeHref} from '../lib/navigation-links';
const {locale}=useI18n(),zh=computed(()=>locale.value==='zh-CN');const text=(cn:string,en:string)=>zh.value?cn:en;const feed=useNewsroom();
const tab=ref('news'),category=ref('all'),topic=ref(''),search=ref(''),language=ref(zh.value?'zh':'all'),pageSize=ref(24),video=ref('formula1'),consent=ref(false);
watch(locale,()=>{language.value=zh.value?'zh':'all';});
const topics=computed(()=>feed.data.value?.topics.filter(t=>category.value==='all'||t.kind===category.value)||[]);
watch(category,()=>{topic.value='';pageSize.value=24;});watch([topic,search,language],()=>{pageSize.value=24;});
const results=computed(()=>{const now=Date.now();if(!feed.data.value?.expiresAt||Date.parse(feed.data.value.expiresAt)<now)return [];return feed.data.value.items.filter(item=>(category.value==='all'||item.categories.includes(category.value as 'driver'|'team'|'race'))&&(!topic.value||item.topics.includes(topic.value))&&(language.value==='all'||item.language==='zh'||!!item.titleZh)&&(!search.value||[item.title,item.titleZh||'',...item.topics.map(id=>feed.data.value?.topics.find(t=>t.id===id)?.nameZh||'')].some(title=>title.toLowerCase().includes(search.value.trim().toLowerCase()))));});
const selectedTopic=computed(()=>feed.data.value?.topics.find(t=>t.id===topic.value));
const gallery=computed(()=>{const source=[...photos,...racePhotos.map(p=>({id:p.id,team:'Audi',title:p.alt,src:p.src,author:p.credit,license:'Non-commercial editorial use',licenseUrl:p.terms,source:p.source,captured:p.capturedAt}))].map(p=>({...p,imageHref:assetUrl(p.src)}));const all=[...source,...(feed.data.value?.photos?.items||[]).map(p=>({...p,imageHref:apiUrl(p.src)}))];const unique=[...new Map(all.map(p=>[p.source,p])).values()];const selected=selectedTopic.value;return unique.filter(p=>{if(!selected)return true;if(selected.kind==='team')return p.team===selected.name;if(selected.kind==='driver')return p.title.toLowerCase().includes(selected.name.split(' ').at(-1)!.toLowerCase());return p.title.toLowerCase().includes(selected.name.replace(' Grand Prix',' GP').toLowerCase());}).sort((a,b)=>b.captured.localeCompare(a.captured));});
async function selectTopic(id:string){category.value='all';await nextTick();topic.value=id;}
const chosen=computed(()=>videoSources.find(v=>v.id===video.value)!);watch(video,()=>{consent.value=false;});watch(tab,()=>{consent.value=false;});
const player=computed(()=>apiUrl('/media/news-player.html')+'?channel='+chosen.value.id+'&lang='+(zh.value?'zh':'en'));
const stamp=(value:string|null)=>value?new Date(value).toLocaleString(locale.value):text('等待首次同步','Awaiting first sync');
const healthy=computed(()=>feed.connected.value&&feed.data.value?.status==='ready');
</script>
<template><div class="page-heading"><div><p class="eyebrow">NOBI / NEWSROOM</p><h1 tabindex="-1">{{text('F1 新闻专栏','F1 Newsroom')}}</h1><p class="muted">{{text('车手、车队与赛事动态，一处关注。','Drivers, teams and racing stories, together.')}}</p></div><RouterLink class="button" to="/news">{{text('赛事战报','Race briefs')}} ↗</RouterLink></div>
<section class="newsroom-status" aria-live="polite"><span class="newsroom-dot" :class="{online:healthy}"/><div><strong>{{feed.error.value?text('连接暂不可用，自动重试中','Connection unavailable; retrying'):healthy?text('正在接收新闻更新','Receiving news updates'):text('自动更新中','Automatic updates')}}</strong><p class="caption">{{text('最近同步：','Last sync: ')}}{{stamp(feed.data.value?.syncedAt||null)}}</p><details class="caption"><summary>{{text('更新说明与来源时间','Update details and source time')}}</summary><p>{{text('每 2 分钟检查新闻源；来源约每 15 分钟发布一批，可能延迟。新内容推送到本页。索引发现时间不等于文章发布时间。','News source checked every 2 minutes. Source batches are about 15 minutes apart and may be delayed. New content is pushed to this page. Indexed time is not publication time.')}}</p><p>{{text('最近检查：','Last checked: ')}}{{stamp(feed.data.value?.checkedAt||null)}} · {{text('来源批次：','Source batch: ')}}{{stamp(feed.data.value?.datasetAt||null)}}</p></details></div><button class="button" @click="feed.reload">{{text('刷新','Refresh')}}</button></section>
<p v-if="feed.data.value?.status==='delayed'||feed.data.value?.status==='unavailable'" class="notice" role="status">{{text('来源暂有延迟；可用内容保留来源时间，恢复后自动更新。','Source is delayed. Available content retains its source time and updates when service recovers.')}}</p>
<div class="newsroom-tabs" role="group" :aria-label="text('内容类型','Content type')"><button v-for="[key,cn,en] in [['news','新闻','News'],['photos','图片','Photos'],['videos','视频','Videos']]" :key="key" class="button" :aria-pressed="tab===key" @click="tab=key">{{text(cn!,en!)}}</button></div>
<div v-if="tab!=='videos'" class="newsroom-filters"><label>{{text('分类','Category')}}<select v-model="category" :aria-label="text('分类','Category')"><option value="all">{{text('全部动态','All stories')}}</option><option value="driver">{{text('车手','Drivers')}}</option><option value="team">{{text('车队','Teams')}}</option><option value="race">{{text('赛事','Races')}}</option></select></label><label>{{text('关注对象','Subject')}}<select v-model="topic" :aria-label="text('关注对象','Subject')"><option value="">{{text('全部对象','All subjects')}}</option><option v-for="item in topics" :key="item.id" :value="item.id">{{zh?item.nameZh:item.name}}</option></select></label><template v-if="tab==='news'"><label>{{text('语言','Language')}}<select v-model="language" :aria-label="text('语言','Language')"><option value="zh">{{text('中文（含机器译题）','Chinese & machine translations')}}</option><option value="all">{{text('全部语种（保留原题）','All languages (original titles)')}}</option></select></label><label>{{text('搜索标题','Search headlines')}}<input v-model="search" :aria-label="text('搜索标题','Search headlines')" type="search" maxlength="100" :placeholder="text('输入车手、车队或赛事关键词','Driver, team or event')"/></label></template></div>
<template v-if="tab==='news'"><p class="caption newsroom-rights">{{text('新闻索引：','News index: ')}}<a href="https://www.gdeltproject.org/" target="_blank" rel="noopener noreferrer">GDELT Project ↗</a> · {{text('关键词自动匹配分类；仅展示索引原题与链接，不复制正文或原站图片。报道及其观点归发布者，请到来源核对；非官方新闻服务。','Subjects are matched by keywords. Index titles and links only; no copied article bodies or publisher images. Reporting and opinions belong to the publisher; check the original source. Unofficial service.')}}</p>
<div class="newsroom-grid"><article v-for="item in results.slice(0,pageSize)" :key="item.id" class="newsroom-card"><p class="eyebrow">{{item.publisher}} · {{item.language==='zh'?text('中文','Chinese'):text('外文原题','Original title')}}</p><h2><a :href="safeHref(item.url)" target="_blank" rel="noopener noreferrer">{{zh?(item.titleZh||item.title):item.title}} ↗</a></h2><details v-if="zh&&item.language!=='zh'"><summary>{{item.translation==='edited'?'本站中文整理 · 查看原题':item.titleZh?'机器译题 · 查看原题':'外文原题（中文暂不可用）'}}</summary><p lang="en">{{item.title}}</p><p v-if="item.translation==='machine'" class="caption">MyMemory · 机器翻译，仅供参考，以原题和原文为准。</p></details><p class="caption">{{text('索引发现：','Indexed: ')}}{{stamp(item.indexedAt)}}</p><div class="newsroom-tags"><button v-for="id in item.topics.slice(0,4)" :key="id" @click="selectTopic(id)">{{zh?feed.data.value?.topics.find(t=>t.id===id)?.nameZh:feed.data.value?.topics.find(t=>t.id===id)?.name}}</button></div><a class="button" :href="safeHref(item.url)" target="_blank" rel="noopener noreferrer">{{text('到来源阅读','Read at source')}} ↗</a></article></div><p v-if="!results.length" class="empty-inline" role="status">{{feed.data.value?.status==='pending'?text('正在首次同步新闻索引，请稍后再看。','Synchronizing the first news index.'):text('当前筛选下暂无新闻；可切换“全部语种”或其他对象。','No stories match these filters. Try all languages or another subject.')}}</p><button v-if="results.length>pageSize" class="button" @click="pageSize+=24">{{text('加载更多','Load more')}}</button></template>
<template v-if="tab==='photos'"><p class="caption">{{text('自动相册最近同步：','Auto-gallery last sync: ')}}{{stamp(feed.data.value?.photos?.syncedAt||null)}} · {{text('每 30 分钟检查新上传的开放许可照片；另保留已核验的资料相册。','New openly licensed uploads checked every 30 minutes; the curated archive remains available.')}}</p><p class="caption">{{text('已核验许可的赛车照片资料库，按拍摄日期排序；照片独立署名，非新闻原站配图或实时画面。','Licensed racing photo library, sorted by capture date. Separately credited photographs, not publisher article imagery or live pictures.')}}</p><div class="newsroom-grid"><figure v-for="photo in gallery" :key="photo.id" class="newsroom-photo"><img :src="photo.imageHref" :alt="photo.title" width="1920" height="1280" loading="lazy"/><figcaption><strong>{{photo.team}}</strong><p>{{photo.captured}} · {{photo.author}}</p><a :href="safeHref(photo.source)" target="_blank" rel="noopener noreferrer">{{text('照片来源','Photo source')}} ↗</a> · <a :href="safeHref(photo.licenseUrl)" target="_blank" rel="noopener noreferrer">{{photo.license}} ↗</a></figcaption></figure></div><p v-if="!gallery.length" class="empty-inline">{{text('该对象暂无已核验图片，可查看全部图片。','No verified photos for this subject; try all photos.')}}</p></template>
<section v-if="tab==='videos'" class="newsroom-video"><label>{{text('官方视频频道','Official video channel')}}<select v-model="video" :aria-label="text('官方视频频道','Official video channel')"><option v-for="source in videoSources" :key="source.id" :value="source.id">{{zh?source.nameZh:source.name}}</option></select></label><h2>{{zh?chosen.nameZh:chosen.name}}</h2><p>{{text('频道上传列表由 YouTube 直接提供，新增视频随频道列表更新；播放器内可切换视频。视频语言、字幕、地区和嵌入许可由频道及平台决定。','YouTube supplies the channel upload list and updates it when videos are added. Switch videos inside the player. Language, captions, region and embedding availability depend on the channel and platform.')}}</p><div v-if="!consent" class="newsroom-consent"><p>{{text('加载后将连接 YouTube/Google，提供方可能处理 IP、浏览器及播放数据。默认不加载第三方播放器、不自动播放。','Loading connects to YouTube/Google, which may process IP, browser and playback data. The player is not loaded by default and autoplay is off.')}}</p><p><a href="https://policies.google.com/privacy" target="_blank" rel="noopener noreferrer">{{text('Google 隐私政策','Google privacy policy')}} ↗</a></p><button class="button primary" @click="consent=true">{{text('同意并加载官方播放器','Load official player')}}</button></div><template v-else><iframe :key="video" class="newsroom-player" :src="player" :title="chosen.name" referrerpolicy="strict-origin-when-cross-origin" allow="encrypted-media; picture-in-picture; fullscreen" allowfullscreen/><button class="button" @click="consent=false">{{text('关闭播放器','Close player')}}</button></template><p><a class="button" :href="chosen.url" target="_blank" rel="noopener noreferrer">{{text('在 YouTube 查看频道最新视频','Latest videos on YouTube')}} ↗</a></p><p class="caption">{{text('若网络或版权限制导致无法嵌入播放，请使用频道原站入口。','If the network or rights settings prevent embedding, use the original channel link.')}}</p></section>
</template>
